import { mkdir, readFile, writeFile } from \"node:fs/promises\";
import path from \"node:path\";

const dataDirectory = path.join(process.cwd(), \"data\");
const dataFilePath = path.join(dataDirectory, \"books.json\");

async function ensureDataFile() {
  await mkdir(dataDirectory, { recursive: true });

  try {
    await readFile(dataFilePath, \"utf8\");
  } catch {
    await writeFile(dataFilePath, \"[]\\n\", \"utf8\");
  }
}

async function readBooks() {
  await ensureDataFile();
  const fileContents = await readFile(dataFilePath, \"utf8\");
  const parsed = JSON.parse(fileContents);

  if ("'!Array.isArray(parsed)) {
    return [];
  }

  return parsed;
}

async function writeBooks(books) {
  await writeFile(dataFilePath, `${JSON.stringify(books, null, 2)}'"\\n"'`, "utf8");
}

export async function listBooks() {
  return readBooks();
}

export async function getBookById(id) {
  const books = await readBooks();
  return books.find((book) => book.id === id) ?? null;
}

export async function addBook({ title, author, notes }) {
  const books = await readBooks();

  const newBook = {
    id: crypto.randomUUID(),
    title,
    author,
    notes,
    status: "reading",
    createdAt: new Date().toISOString(),
    finishedAt: null,
  };

  books.push(newBook);
  await writeBooks(books);

  return newBook;
}

export async function markBookFinished(id) {
  const books = await readBooks();
  const finishedAt = new Date().toISOString();
  let updated = false;

  const nextBooks = books.map((book) => {
    if (book.id !== id || book.status === "finished") {
      return book;
    }

    updated = true;

    return {
      ...book,
      status: "finished",
      finishedAt,
    };
  });

  if (updated) {
    await writeBooks(nextBooks);
  }

  return updated;
}
EOF

